package io.github.diodeme.ji.session.sqlite;

import io.github.diodeme.ji.storage.sqlite.SqliteMigration;
import io.github.diodeme.ji.storage.sqlite.SqliteMigrationManager;
import io.github.diodeme.ji.storage.sqlite.SqliteSchema;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;

/** Forward-only catalog for the standalone Session database. */
final class SessionDatabaseMigrations {
    private static final Set<String> COLUMNS = Set.of(
            "session_id", "revision", "created_at", "working_directory", "name", "updated_at", "document");

    private SessionDatabaseMigrations() {}

    static void migrate(Path database) {
        new SqliteMigrationManager(database, "session", List.of(new SqliteMigration(1, "canonical-sessions", List.of(
                """
                CREATE TABLE IF NOT EXISTS ji_sessions (
                  session_id TEXT PRIMARY KEY,
                  revision INTEGER NOT NULL CHECK (revision >= 0),
                  created_at TEXT NOT NULL,
                  working_directory TEXT NOT NULL,
                  name TEXT,
                  updated_at TEXT NOT NULL,
                  document BLOB NOT NULL
                )
                """,
                "CREATE INDEX IF NOT EXISTS ji_sessions_summary_page ON ji_sessions(working_directory, updated_at DESC, session_id ASC)",
                "CREATE INDEX IF NOT EXISTS ji_sessions_summary_page_all ON ji_sessions(updated_at DESC, session_id ASC)"))), connection -> {
            var schema = SqliteSchema.tables(connection);
            if (schema.isEmpty()) return 0;
            return schema.keySet().equals(Set.of("ji_sessions")) && schema.get("ji_sessions").equals(COLUMNS) ? 1 : -1;
        }).migrate();
    }
}
